<metadata name="ResponseBody" value='@{
    var body = ((IResponse)context.Response).Body?.As(preserveContent: true);
    return !string.IsNullOrWhiteSpace(body) ? body : "";
}' />

<metadata name="ResponseStatusReason" value='@(string.IsNullOrWhiteSpace(context.Response.StatusReason?.ToString()) ? "" : context.Response.StatusReason.ToString())' />
